let latestMarker = toscalar(CIEM_AttackPaths_CL | extend RecordType = tostring(column_ifexists('RecordType', 'Path')) | where RecordType == 'Snapshot' | summarize max(TimeGenerated));
let latestSnapshot = coalesce(latestMarker, toscalar(CIEM_AttackPaths_CL | summarize max(TimeGenerated)));
CIEM_AttackPaths_CL
| where TimeGenerated {TimeRange}
| extend RecordType = tostring(column_ifexists('RecordType', 'Path')), Cloud = tostring(column_ifexists('Cloud', 'Unknown')), ProviderSet = tostring(column_ifexists('ProviderSet', column_ifexists('Cloud', 'Unknown')))
| where RecordType != 'Snapshot' and isnotempty(AttackPathId)
| where '{CloudProvider}' == 'All' or ProviderSet has '{CloudProvider}'
| summarize FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated), Cloud = any(Cloud) by AttackPathId
| extend Status = iff(LastSeen >= latestSnapshot - 5m, 'Active', 'Resolved')
| summarize ['Tracked paths']=count(), ['Currently active']=countif(Status == 'Active'), ['Resolved']=countif(Status == 'Resolved'), ['Median active age (days)']=percentile(datetime_diff('day', now(), FirstSeen), 50) by Cloud

let latestMarker = toscalar(CIEM_AttackPaths_CL | extend RecordType = tostring(column_ifexists('RecordType', 'Path')) | where RecordType == 'Snapshot' | summarize max(TimeGenerated));
let latestSnapshot = coalesce(latestMarker, toscalar(CIEM_AttackPaths_CL | summarize max(TimeGenerated)));
let scoped = CIEM_AttackPaths_CL | where TimeGenerated {TimeRange} | extend RecordType = tostring(column_ifexists('RecordType', 'Path')), Cloud = tostring(column_ifexists('Cloud', 'Unknown')), ProviderSet = tostring(column_ifexists('ProviderSet', column_ifexists('Cloud', 'Unknown'))) | where RecordType != 'Snapshot' and isnotempty(AttackPathId) | where '{CloudProvider}' == 'All' or ProviderSet has '{CloudProvider}';
let newByDay = scoped | summarize FS = min(TimeGenerated), Cloud = any(Cloud) by AttackPathId | summarize New = count() by Day = bin(FS, 1d), Cloud;
let resolvedByDay = scoped | summarize LS = max(TimeGenerated), Cloud = any(Cloud) by AttackPathId | where LS < latestSnapshot - 5m | summarize Resolved = count() by Day = bin(LS, 1d), Cloud;
scoped
| summarize Active = dcount(AttackPathId) by Day = bin(TimeGenerated, 1d), Cloud
| join kind=leftouter newByDay on Day, Cloud
| join kind=leftouter resolvedByDay on Day, Cloud
| project Day, Cloud, Active, New = coalesce(New, 0), Resolved = coalesce(Resolved, 0)
| order by Day asc
